/* ==UserStyle==
@name         Dunkin Font for Roblox
@namespace    github.com/yourname
@version      1.0.0
@description  Applies DunkinBold font to Roblox
@match        *://www.roblox.com/*
==/UserStyle== */

@font-face {
    font-family: 'DunkinBold';
    src: url('https://dl.dafont.com/dl/?f=dunkin') format('woff2');
    font-weight: normal;
    font-style: normal;
}

body, div, span, p, a, h1, h2, h3, h4, h5, h6, button, input, label, textarea {
    font-family: 'DunkinBold' !important;
}
